import math

def parse_obj_id(obj_str: str):
    return obj_str.split()[0]

def build_motion_log(doc, scope):
    log = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") != "table":
            continue
        if not node.get("title", "").endswith(": Motion log"):
            continue
        for _, row in table_rows(node):
            frame = int(row.get("frame", ""))
            obj_desc = row.get("object", "")
            oid = parse_obj_id(obj_desc)
            log[(frame, oid)] = {
                "x": float(row.get("x", "0")),
                "y": float(row.get("y", "0")),
                "vx": float(row.get("vx", "0")),
                "vy": float(row.get("vy", "0")),
                "s": float(row.get("speed", "0")),
            }
    return log

def gather_collision_distances(doc):
    dists = []
    for node in doc.get("nodes", []):
        if node.get("kind") != "list":
            continue
        title = node.get("title", "")
        if not title.endswith(": Events") or not title.startswith("Video "):
            continue
        # Get the parent video node
        parent_id = node.get("parent_id")
        if not parent_id:
            continue
        video_node = node_by_id(doc, parent_id)
        video_title = video_node.get("title")
        # Build motion log for this video
        motion_log = build_motion_log(doc, video_title)
        for i, line in enumerate(node.get("lines", [])):
            if "collides with" not in line:
                continue
            # Extract frame number
            frame_match = re.match(r"Frame (\d+):", line)
            if not frame_match:
                continue
            f = int(frame_match.group(1))
            eids = _extract_entities_from_line(line)
            if len(eids) != 2:
                continue
            pos1 = motion_log.get((f, eids[0]))
            pos2 = motion_log.get((f, eids[1]))
            if pos1 is None or pos2 is None:
                continue
            dist = math.hypot(pos1["x"] - pos2["x"], pos1["y"] - pos2["y"])
            dists.append(dist)
    return dists

