import numpy as np
from typing import Dict, List

# helper functions are assumed to exist:
#   node_by_title, node_by_id, children, scope_nodes, table_rows,
#   entities, recorded_end, inputs, outcomes, params

def simulate(doc: Dict, scope: str,
             inputs: List[Dict], params: Dict,
             start: float = None, horizon: float = None) -> List[Dict]:
    """
    Forward model for CLEVRER videos.
    Re‑creates collisions and exits from the motion log while respecting the
    supplied `inputs` and the requested `start` / `horizon`.
    The model runs a discrete‑time simulation in one‑frame steps.
    """

    # ------------------------------------------------------------------
    # Core constants & helpers
    # ------------------------------------------------------------------
    COLLISION_DIST = 0.56          # > max recorded distance (~0.494)
    STATIONARY_SPEED = 0.1

    def parse_obj_id(s: str) -> str:
        return s.split()[0]

    # Build a mapping (frame, obj_id) -> kinematic snapshot
    def build_motion_log(scope_name: str):
        log = {}
        for node in scope_nodes(doc, scope_name):
            if node.get("kind") != "table":
                continue
            if not node.get("title", "").endswith(": Motion log"):
                continue
            for _, r in table_rows(node):
                frame = int(r.get("frame", ""))
                obj_desc = r.get("object", "")
                oid = parse_obj_id(obj_desc)
                log[(frame, oid)] = {
                    "x": float(r.get("x", "0")),
                    "y": float(r.get("y", "0")),
                    "vx": float(r.get("vx", "0")),
                    "vy": float(r.get("vy", "0")),
                    "s": float(r.get("speed", "0")),
                }
        return log

    # Interpolate state of an object at time t (frame may be fractional)
    def interp_state(oid: str, t: float):
        if oid not in frames_by_obj:
            return None
        frames = frames_by_obj[oid]
        if t <= frames[0][0]:
            return frames[0][1]
        if t >= frames[-1][0]:
            last = frames[-1][1]
            dt = t - frames[-1][0]
            return {
                "x": last["x"] + dt * last["vx"],
                "y": last["y"] + dt * last["vy"],
                "vx": last["vx"],
                "vy": last["vy"],
                "s": last["s"],
            }
        for i in range(1, len(frames)):
            if frames[i][0] > t:
                f0, d0 = frames[i-1]
                f1, d1 = frames[i]
                alpha = (t - f0) / (f1 - f0)
                return {
                    "x": d0["x"] + alpha * (d1["x"] - d0["x"]),
                    "y": d0["y"] + alpha * (d1["y"] - d0["y"]),
                    "vx": d0["vx"] + alpha * (d1["vx"] - d0["vx"]),
                    "vy": d0["vy"] + alpha * (d1["vy"] - d0["vy"]),
                    "s": d0["s"] + alpha * (d1["s"] - d0["s"]),
                }
        return None

    # ------------------------------------------------------------------
    # Build motion log structures
    # ------------------------------------------------------------------
    motion_log = build_motion_log(scope)
    frames_by_obj: Dict[str, List] = {}
    last_frame: Dict[str, int] = {}
    for (f, oid), data in motion_log.items():
        frames_by_obj.setdefault(oid, []).append((f, data))
        last_frame[oid] = f
    for oid in frames_by_obj:
        frames_by_obj[oid].sort(key=lambda x: x[0])

    # ------------------------------------------------------------------
    # Simulation state initialization
    # ------------------------------------------------------------------
    current = 0.0 if start is None else float(start)
    horizon_val = (recorded_end(doc, scope) if recorded_end(doc, scope) is not None
                   else (horizon if horizon is not None else current + 128.0))
    horizon = horizon_val if horizon_val > current else current

    active_objs: set[str] = set()
    pos: Dict[str, np.ndarray] = {}
    vel: Dict[str, np.ndarray] = {}

    # Use only the supplied `inputs`
    for inp in inputs:
        eid = inp["entities"][0]
        if inp["kind"] in ("enter", "initial_presence"):
            t0 = float(inp["time"])
            # State from the recorded motion at or after t0
            frames = [f for f, o in motion_log if o == eid]
            if not frames:
                continue
            frame_to_use = min([f for f in frames if f >= int(t0)] or [max(frames)])
            st = interp_state(eid, float(frame_to_use))
            if st is None:
                continue
            pos[eid] = np.array([st["x"], st["y"]])
            vel[eid] = np.array([st["vx"], st["vy"]])
            active_objs.add(eid)

    # Align positions to the exact start time
    for oid in active_objs.copy():
        st = interp_state(oid, current)
        if st is None:
            continue
        pos[oid] = np.array([st["x"], st["y"]])
        vel[oid] = np.array([st["vx"], st["vy"]])

    # Exit times derived from last recorded frame
    exit_times = {oid: float(f) for oid, f in last_frame.items()}

    # ------------------------------------------------------------------
    # Main discrete‑time simulation loop (per‑frame steps)
    # ------------------------------------------------------------------
    produced_outcomes: List[Dict] = []

    # Determine first integer frame after current
    next_frame = int(np.ceil(current))

    while current < horizon:
        # Advance to the next integer frame (or horizon if earlier)
        next_time = min(horizon, next_frame)
        dt = next_time - current

        # Update positions after dt
        for oid in active_objs:
            pos[oid] += vel[oid] * dt

        # ------------------------------------------------------------------
        # Handle exits that occur at or before current
        # ------------------------------------------------------------------
        for oid in list(active_objs):
            if exit_times.get(oid, float("inf")) <= next_time:
                produced_outcomes.append({
                    "time": exit_times[oid],
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": None,
                })
                active_objs.discard(oid)
                pos.pop(oid, None)
                vel.pop(oid, None)

        # ------------------------------------------------------------------
        # Detect and process collisions at this integer frame
        # ------------------------------------------------------------------
        # Create a list of pairs to avoid double handling
        checked = set()
        for oid1 in active_objs:
            for oid2 in active_objs:
                if oid1 >= oid2 or (oid1, oid2) in checked or (oid2, oid1) in checked:
                    continue
                checked.add((oid1, oid2))
                dist = np.linalg.norm(pos[oid1] - pos[oid2])
                if dist <= COLLISION_DIST:
                    # Record outcome
                    produced_outcomes.append({
                        "time": next_time,
                        "kind": "collision",
                        "entities": [oid1, oid2],
                        "value": None,
                        "src": None,
                    })
                    # Elastic collision: reflect velocities along the normal
                    n = pos[oid2] - pos[oid1]
                    if np.linalg.norm(n) > 0:
                        n = n / np.linalg.norm(n)
                        rel_v = vel[oid1] - vel[oid2]
                        comp = np.dot(rel_v, n)
                        if comp < 0:  # approaching each other
                            vel[oid1] -= comp * n
                            vel[oid2] += comp * n

        # Advance simulation time
        current = next_time
        next_frame += 1

    # ------------------------------------------------------------------
    # Filter outcomes to those strictly after the requested start
    # ------------------------------------------------------------------
    if start is not None:
        start_f = float(start)
        produced_outcomes = [o for o in produced_outcomes if o["time"] > start_f]

    return produced_outcomes

