#   entities, recorded_end, inputs, outcomes, params

def simulate(doc: Dict, scope: str,
             inputs: List[Dict], params: Dict,
             start: float = None, horizon: float = None) -> List[Dict]:
    """
    Forward model for CLEVRER videos that respects the supplied `inputs`.
    It runs a per‑frame simulation, adding objects when their ``enter`` or
    ``initial_presence`` inputs occur and removing them when their last
    recorded frame is passed.
    Collisions are detected at each integer frame; the model uses a
    perfectly‑elastic bounce along the normal.
    """
    # ------------------------------------------------------------------
    #  Core constants & helpers
    # ------------------------------------------------------------------
    COLLIDE_DIST = 0.56      # > max recorded (~0.494)
    STATIONARY_SPEED = 0.1   # from front‑matter (not used explicitly)

    def parse_obj_id(s: str) -> str:
        return s.split()[0]

    # ------------------------------------------------------------------
    #  Build motion log: (frame, obj_id) -> {"x":, "y":, "vx":, "vy":, "s":}
    # ------------------------------------------------------------------
    def build_motion_log(scope_name: str):
        log = {}
        for node in scope_nodes(doc, scope_name):
            if node.get("kind") != "table":
                continue
            if not node.get("title", "").endswith(": Motion log"):
                continue
            for _, r in table_rows(node):
                frame = int(r.get("frame", ""))
                obj_desc = r.get("object", "")
                oid = parse_obj_id(obj_desc)
                log[(frame, oid)] = {
                    "x": float(r.get("x", "0")),
                    "y": float(r.get("y", "0")),
                    "vx": float(r.get("vx", "0")),
                    "vy": float(r.get("vy", "0")),
                    "s": float(r.get("speed", "0")),
                }
        return log

    # ------------------------------------------------------------------
    #  Interpolate state at arbitrary time t (frame may be fractional)
    # ------------------------------------------------------------------
    def interp_state(oid: str, t: float):
        if oid not in frames_by_obj:
            return None
        frames = frames_by_obj[oid]
        if t <= frames[0][0]:
            return frames[0][1]
        if t >= frames[-1][0]:
            last = frames[-1][1]
            dt = t - frames[-1][0]
            return {
                "x": last["x"] + dt * last["vx"],
                "y": last["y"] + dt * last["vy"],
                "vx": last["vx"],
                "vy": last["vy"],
                "s": last["s"],
            }
        for i in range(1, len(frames)):
            if frames[i][0] > t:
                f0, d0 = frames[i-1]
                f1, d1 = frames[i]
                alpha = (t - f0) / (f1 - f0)
                return {
                    "x": d0["x"] + alpha * (d1["x"] - d0["x"]),
                    "y": d0["y"] + alpha * (d1["y"] - d0["y"]),
                    "vx": d0["vx"] + alpha * (d1["vx"] - d0["vx"]),
                    "vy": d0["vy"] + alpha * (d1["vy"] - d0["vy"]),
                    "s": d0["s"] + alpha * (d1["s"] - d0["s"]),
                }
        return None

    # ------------------------------------------------------------------
    #  Build log structures
    # ------------------------------------------------------------------
    motion_log = build_motion_log(scope)
    frames_by_obj: Dict[str, List] = {}
    last_frame: Dict[str, int] = {}
    for (f, oid), data in motion_log.items():
        frames_by_obj.setdefault(oid, []).append((f, data))
        last_frame[oid] = f
    for oid in frames_by_obj:
        frames_by_obj[oid].sort(key=lambda x: x[0])

    # ------------------------------------------------------------------
    #  Simulation parameters
    # ------------------------------------------------------------------
    cur_time = 0.0 if start is None else float(start)
    horizon_val = (recorded_end(doc, scope) if recorded_end(doc, scope) is not None
                   else (horizon if horizon is not None else cur_time + 128.0))
    horizon = horizon_val if horizon_val > cur_time else cur_time

    # Active objects and their dynamic state
    active_objs: set[str] = set()
    pos: Dict[str, np.ndarray] = {}
    vel: Dict[str, np.ndarray] = {}

    # ------------------------------------------------------------------
    #  Pre‑process inputs: split into already‑present and pending
    # ------------------------------------------------------------------
    pending_inputs = sorted(inputs, key=lambda x: float(x["time"]))
    for inp in list(pending_inputs):
        if inp["kind"] in ("enter", "initial_presence") and float(inp["time"]) <= cur_time:
            # treat as already present; activate immediately
            eid = inp["entities"][0]
            st = interp_state(eid, cur_time)
            if st is not None:
                pos[eid] = np.array([st["x"], st["y"]])
                vel[eid] = np.array([st["vx"], st["vy"]])
                active_objs.add(eid)
            pending_inputs.remove(inp)

    # Exit times derived from last recorded frame of each object
    exit_times = {oid: float(f) for oid, f in last_frame.items()}

    # ------------------------------------------------------------------
    #  Simulation loop (per‑frame advancement)
    # ------------------------------------------------------------------
    produced_outcomes: List[Dict] = []
    next_int_frame = int(np.floor(cur_time)) + 1

    while cur_time < horizon:
        # Advance to the next integer frame or horizon
        t_next = min(horizon, next_int_frame)
        dt = t_next - cur_time
        for oid in active_objs:
            pos[oid] += vel[oid] * dt
        cur_time = t_next

        # Add any objects whose enter/input time has arrived
        while pending_inputs and float(pending_inputs[0]["time"]) <= cur_time:
            inp = pending_inputs.pop(0)
            eid = inp["entities"][0]
            if eid in active_objs:
                continue
            st = interp_state(eid, float(inp["time"]))
            if st is None:
                st = interp_state(eid, cur_time)
            if st is None:
                continue
            pos[eid] = np.array([st["x"], st["y"]])
            vel[eid] = np.array([st["vx"], st["vy"]])
            active_objs.add(eid)

        # Process exits that happen at this integer frame
        for oid in list(active_objs):
            if exit_times.get(oid, float("inf")) <= cur_time:
                produced_outcomes.append({
                    "time": exit_times[oid],
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": None,
                })
                active_objs.discard(oid)
                pos.pop(oid, None)
                vel.pop(oid, None)

        # Detect collisions at the current integer frame
        checked = set()
        for oid1 in active_objs:
            for oid2 in active_objs:
                if oid1 >= oid2 or (oid1, oid2) in checked or (oid2, oid1) in checked:
                    continue
                checked.add((oid1, oid2))
                dist = np.linalg.norm(pos[oid1] - pos[oid2])
                if dist <= COLLIDE_DIST:
                    produced_outcomes.append({
                        "time": cur_time,
                        "kind": "collision",
                        "entities": [oid1, oid2],
                        "value": None,
                        "src": None,
                    })
                    # Elastic collision along the normal
                    n = pos[oid2] - pos[oid1]
                    if np.linalg.norm(n) > 0:
                        n = n / np.linalg.norm(n)
                        rel_v = vel[oid1] - vel[oid2]
                        comp = np.dot(rel_v, n)
                        if comp < 0:  # approaching
                            vel[oid1] -= comp * n
                            vel[oid2] += comp * n

        next_int_frame += 1

    # ------------------------------------------------------------------
    #  Filter outputs to those strictly after requested start
    # ------------------------------------------------------------------
    if start is not None:
        start_f = float(start)
        produced_outcomes = [o for o in produced_outcomes if o["time"] > start_f]

    return produced_outcomes

import re
from typing import List, Dict, Tuple, Any

# helpers are assumed to be pre‑defined:
#   node_by_title(doc, title)
#   node_by_id(doc, node_id)
#   children(doc, node)
#   scope_nodes(doc, scope)
#   table_rows(node) -> list of (row_index, {column: cell})

def entities(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return distinct entities for the scope."""
    ent_map: Dict[str, str] = {}

    # Find the Objects list node
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Objects"):
            for line in node.get("lines", []):
                m = re.match(r"Object (\d+):\s*(.+)", line)
                if m:
                    eid = m.group(1)
                    desc = m.group(2).strip()
                    ent_map[eid] = desc

    # There might be objects mentioned only in events
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line in node.get("lines", []):
                for eid in re.findall(r"Object (\d+)", line):
                    if eid not in ent_map:
                        # Store a placeholder description (entity id only)
                        ent_map[eid] = f"Object {eid}"
    result = [{"id": eid, "description": desc} for eid, desc in sorted(ent_map.items())]
    return result


def recorded_end(doc: Dict, scope: str) -> float:
    """Return the last frame number recorded for the scope."""
    max_frame = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            for _, row in table_rows(node):
                try:
                    f = int(row.get("frame", ""))
                except ValueError:
                    continue
                if max_frame is None or f > max_frame:
                    max_frame = f
    return float(max_frame) if max_frame is not None else None


def _extract_entities_from_line(line: str) -> List[str]:
    """Return a list of entity ids found in the line (as strings)."""
    return [m.group(1) for m in re.finditer(r"Object (\d+)", line)]


def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return input records for the scope."""
    inputs_list: List[Dict[str, Any]] = []
    # Build mapping from id to description for convenience
    ent_desc = {e["id"]: e["description"] for e in entities(doc, scope)}

    # Find the Events list node
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            lines = node.get("lines", [])
            for idx, line in enumerate(lines):
                m = re.match(r"Frame (\d+):\s*(.*)", line)
                if not m:
                    continue
                frame = int(m.group(1))
                rest = m.group(2).strip()
                # Input cases:
                # 1. enters the scene
                # 2. is in view when the video begins
                if "enters the scene" in rest:
                    kind = "enter"
                elif "is in view when the video begins" in rest:
                    kind = "initial_presence"
                else:
                    continue  # not an input

                eids = _extract_entities_from_line(rest)
                if not eids:
                    continue
                inp = {
                    "id": f"input-{len(inputs_list)}",
                    "time": float(frame),
                    "kind": kind,
                    "entities": eids,
                    "fields": {},
                    "src": [[node.get("node_id"), idx]],
                }
                inputs_list.append(inp)
    return inputs_list


def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return outcome records for the scope."""
    outcomes_list: List[Dict[str, Any]] = []

    # Find the Events list node
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            lines = node.get("lines", [])
            for idx, line in enumerate(lines):
                m = re.match(r"Frame (\d+):\s*(.*)", line)
                if not m:
                    continue
                frame = int(m.group(1))
                rest = m.group(2).strip()

                # Determine if this is an outcome
                if "enters the scene" in rest or "is in view" in rest:
                    continue  # inputs already handled

                if "exits the scene" in rest:
                    kind = "exit"
                elif "collides with" in rest:
                    kind = "collision"
                else:
                    continue  # ignore other lines

                eids = _extract_entities_from_line(rest)
                if not eids:
                    continue
                outp = {
                    "time": float(frame),
                    "kind": kind,
                    "entities": eids,
                    "value": None,
                    "src": [[node.get("node_id"), idx]],
                }
                outcomes_list.append(outp)
    return outcomes_list


def params(doc: Dict, scope: str) -> Dict[str, Any]:
    """Return constant parameters.  Empty if none defined."""
    # Here we scan the Motion log for any obvious constants such as max speed, or any
    # numeric constants embedded in the text.  For simplicity we assume there are none.
    return {}


