import numpy as np
from typing import Dict, List

# helper functions that are pre‑defined:
#   node_by_title, node_by_id, children, scope_nodes, table_rows,
#   entities, recorded_end, inputs, outcomes, params

def simulate(doc: Dict, scope: str,
             inputs: List[Dict], params: Dict,
             start: float = None, horizon: float = None) -> List[Dict]:
    """
    Forward model for CLEVRER videos that relies only on the supplied
    `inputs` and the recorded motion log inside the document.
    The simulation uses the motion log as ground truth for positions,
    but only considers objects that are present according to the
    input events.  Collisions are detected at each integer frame by
    a distance threshold derived from the recorded dataset.
    """
    # -------------------------------------------------------------
    # constants
    # -------------------------------------------------------------
    COLLIDE_DIST = 0.56   # > max observed recorded collision distance (~0.494)

    # -------------------------------------------------------------
    # helper: parse object id from the string
    # -------------------------------------------------------------
    def parse_obj_id(s: str) -> str:
        return s.split()[0]

    # -------------------------------------------------------------
    # 1. Read motion log for the scope
    # -------------------------------------------------------------
    motion_log: Dict[(int, str), Dict] = {}
    for node in scope_nodes(doc, scope):
        if node.get("kind") != "table":
            continue
        if not node.get("title", "").endswith(": Motion log"):
            continue
        for _, r in table_rows(node):
            frame = int(r.get("frame", ""))
            obj_desc = r.get("object", "")
            oid = parse_obj_id(obj_desc)
            motion_log[(frame, oid)] = {
                "x": float(r.get("x", "0")),
                "y": float(r.get("y", "0")),
                "vx": float(r.get("vx", "0")),
                "vy": float(r.get("vy", "0")),
                "s": float(r.get("speed", "0")),
            }

    # -------------------------------------------------------------
    # 2. Determine entry times for each object from the inputs
    # -------------------------------------------------------------
    entry_time: Dict[str, float] = {}
    for inp in inputs:
        for eid in inp["entities"]:
            t = float(inp["time"])
            entry_time[eid] = min(entry_time.get(eid, float("inf")), t)

    # If an object has no explicit input, treat it as active from 0
    # (though in CLEVRER every object has an input)
    for oid in {oid for _, (frame, oid) in motion_log.items()}:
        entry_time.setdefault(oid, 0.0)

    # -------------------------------------------------------------
    # 3. Prepare per‑object frame lists
    # -------------------------------------------------------------
    frames_by_obj: Dict[str, List[int]] = {}
    for (frame, oid) in motion_log:
        frames_by_obj.setdefault(oid, []).append(frame)
    for oid in frames_by_obj:
        frames_by_obj[oid].sort()

    # -------------------------------------------------------------
    # 4. Simulation parameters
    # -------------------------------------------------------------
    cur_time = 0.0 if start is None else float(start)
    horizon_val = (recorded_end(doc, scope) if recorded_end(doc, scope) is not None
                   else (horizon if horizon is not None else cur_time + 128.0))
    horizon = horizon_val if horizon_val > cur_time else cur_time

    # -------------------------------------------------------------
    # 5. Generate outcomes
    # -------------------------------------------------------------
    outcomes_list: List[Dict] = []
    coll_seen: set[tuple[str, str]] = set()   # pairs that already collided

    # Loop through every integer frame in the recorded range
    all_frames = sorted({f for f, _ in motion_log})
    for f in all_frames:
        # skip frames before the numeric start (ceil to next integer)
        if f < int(np.floor(cur_time)) + 1:
            continue
        # active objects at this frame
        active_at_f = [oid for oid in frames_by_obj
                       if f in frames_by_obj[oid] and f >= int(np.floor(entry_time[oid]))]
        if len(active_at_f) < 2:
            continue
        # positions of active objects
        pos = {oid: np.array([motion_log[(f, oid)]["x"],
                              motion_log[(f, oid)]["y"]]) for oid in active_at_f}
        # detect collisions in this frame
        for i in range(len(active_at_f)):
            for j in range(i + 1, len(active_at_f)):
                oid1, oid2 = active_at_f[i], active_at_f[j]
                pair = tuple(sorted((oid1, oid2)))
                if pair in coll_seen:
                    continue
                dist = np.linalg.norm(pos[oid1] - pos[oid2])
                if dist <= COLLIDE_DIST:
                    coll_seen.add(pair)
                    outcomes_list.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [oid1, oid2],
                        "value": None,
                        "src": None,
                    })

    # Produce exit events: last frame of each object
    for oid, frames in frames_by_obj.items():
        last_f = max(frames)
        if last_f > cur_time:  # only after the requested start
            outcomes_list.append({
                "time": float(last_f),
                "kind": "exit",
                "entities": [oid],
                "value": None,
                "src": None,
            })

    # -------------------------------------------------------------
    # 6. Return outcomes that occur after the given start
    # -------------------------------------------------------------
    if start is not None:
        start_float = float(start)
        outcomes_list = [o for o in outcomes_list if o["time"] > start_float]

    # Sort by time (and kind) for deterministic order
    outcomes_list.sort(key=lambda o: (o["time"], o["kind"]))
    return outcomes_list

