def find_row_by_time(rows, entity_id, time):
    # return row for exact time, or nearest before it
    candidates = [r for r in rows.values() if r["object"] and entity_id in r["object"]]
    times = [(float(r["frame"]), r) for r in candidates]
    times.sort()
    for f, r in reversed(times):
        if f <= time:
            return r
    return None

