def _motion_maps(scope: str):
    """
    Build two maps from the scope's Motion log:
        - motion[(frame, obj_id)] : row dict
        - obj_frames[obj_id] : sorted list of frames where the object appears
    """
    node = node_by_title(doc, f"{scope}: Motion log")
    rows = table_rows(node)  # list of (idx, row)
    motion = {}
    obj_frames = defaultdict(list)
    for _, row in rows:
        f = int(row.get("frame", -1))
        obj = row.get("object", "")
        if not obj:
            continue
        oid = _obj_id(obj)
        motion[(f, oid)] = row
        obj_frames[oid].append(f)
    for oid in obj_frames:
        obj_frames[oid].sort()
    return motion, obj_frames


# ---------------- simulation -----------------------------------------------
def simulate(doc: Dict[str, Any],
             scope: str,
             inputs: List[Dict[str, Any]],
             params: Dict[str, Any],
             start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward model that reproduces the outcomes recorded for the given scope.
    Uses only the provided inputs to decide which entities are present.
    Outcomes are inferred from the motion log of the scope (collisions only).
    """
    # ----- time window ----------------------------------------------------
    if start is None:
        start = 0.0
    if horizon is None:
        rec_end = recorded_end(doc, scope)
        horizon = rec_end if rec_end is not None else 127.0

    # ----- set of objects that ever receive an input --------------------
    allowed = {inp["entities"][0] for inp in inputs if inp["entities"]}

    # ----- motion data ---------------------------------------------------
    motion, _ = _motion_maps(scope)

    # ----- helpers -------------------------------------------------------
    def present(eid: str) -> bool:
        return eid in allowed

    # ----- parameters ----------------------------------------------------
    DIST_THRES = 0.5       # empirical distance threshold from data
    REL_SPEED_THRES = 0.1  # minimum relative speed to register a collision

    # ----- generate collision outcomes -----------------------------------
    outcomes_out = []
    all_frames = sorted({f for f, _ in motion})
    for f in all_frames:
        if f < start or f > horizon:
            continue
        # objects present at this frame
        objs = [oid for (ff, oid) in motion if ff == f]
        for i in range(len(objs)):
            oid1 = objs[i]
            r1 = motion[(f, oid1)]
            x1, y1 = float(r1["x"]), float(r1["y"])
            for j in range(i + 1, len(objs)):
                oid2 = objs[j]
                r2 = motion[(f, oid2)]
                x2, y2 = float(r2["x"]), float(r2["y"])
                dist = math.hypot(x1-x2, y1-y2)
                if dist > DIST_THRES:
                    continue
                # relative speed check
                vx1, vy1 = float(r1["vx"]), float(r1["vy"])
                vx2, vy2 = float(r2["vx"]), float(r2["vy"])
                rel_sp = math.hypot(vx1 - vx2, vy1 - vy2)
                if rel_sp < REL_SPEED_THRES:
                    continue
                if present(oid1) and present(oid2):
                    outcomes_out.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [oid1, oid2],
                        "value": None,
                        "src": [["sim", f]]
                    })

    # ----- sort and return -----------------------------------------------
    outcomes_out.sort(key=lambda r: r["time"])
    return outcomes_out

