import math
from typing import List, Dict, Any

# ------------------------------------------------------------------
# Helper: parse the motion log of a given scope.
def _parse_motion_log(doc: Dict, scope: str):
    """Return two dicts:
       - motion: frame -> {obj_id: (vx, vy)}
       - last_frame_per_obj: obj_id -> last recorded frame
    """
    motion = {}
    last_frame_per_obj = {}
    node = node_by_title(doc, f"{scope}: Motion log")
    if not node or node.get("kind") != "table":
        return motion, last_frame_per_obj

    for _, row in table_rows(node):
        try:
            f = int(row.get("frame", ""))
        except ValueError:
            continue
        obj_desc = row.get("object", "")
        if not obj_desc:
            continue
        obj_id = obj_desc.split()[0]          # first token is id
        try:
            vx = float(row.get("vx", ""))
            vy = float(row.get("vy", ""))
        except ValueError:
            continue

        motion.setdefault(f, {})[obj_id] = (vx, vy)
        last_frame_per_obj[obj_id] = f

    return motion, last_frame_per_obj


# ------------------------------------------------------------------
# Main simulation function
def simulate(doc: Dict, scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """
    Forward model that reproduces collision and exit outcomes from the CLEVRER
    motion log.

    Rules implemented:
      * Objects move in straight lines with constant velocity until an event.
      * A perfectly elastic collision swaps the velocity vectors of the two
        colliding objects between consecutive frames.
      * A velocity swap between frames is taken as evidence of a collision.
      * An object exits the scene when it no longer appears in the motion log.
    """
    end_frame = recorded_end(doc, scope)
    if end_frame is None:
        return []  # nothing to simulate

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = end_frame

    start_f = int(math.floor(start))
    horizon_f = int(math.floor(horizon))

    # 1. Parse motion log
    motion, last_frame_per_obj = _parse_motion_log(doc, scope)

    # 2. Detect collisions via velocity swapping
    collision_eps = 1e-3      # tolerance for swapped velocity
    outcomes: List[Dict[str, Any]] = []
    seen_pairs = set()        # prevent duplicate collisions per pair per frame

    for f in sorted(motion.keys()):
        if f <= start_f or f > horizon_f:
            continue
        if f - 1 not in motion:
            continue  # cannot compare without a previous frame
        cur = motion[f]
        prev = motion[f - 1]

        for i in cur:
            if i not in prev:
                continue
            for j in cur:
                if j <= i or j not in prev:
                    continue
                vi_prev = prev[i]
                vj_prev = prev[j]
                vi_cur  = cur[i]
                vj_cur  = cur[j]

                swapped_i = (abs(vi_cur[0] - vj_prev[0]) <= collision_eps
                             and abs(vi_cur[1] - vj_prev[1]) <= collision_eps)
                swapped_j = (abs(vj_cur[0] - vi_prev[0]) <= collision_eps
                             and abs(vj_cur[1] - vi_prev[1]) <= collision_eps)

                if swapped_i and swapped_j:
                    key = (min(i, j), max(i, j), f)
                    if key in seen_pairs:
                        continue
                    seen_pairs.add(key)
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [i, j],
                        "value": None,
                        "src": [],
                    })

    # 3. Detect exits: last recorded frame for each object in the window
    for obj_id, last_f in last_frame_per_obj.items():
        if start_f <= last_f <= horizon_f:
            outcomes.append({
                "time": float(last_f),
                "kind": "exit",
                "entities": [obj_id],
                "value": None,
                "src": [],
            })

    outcomes.sort(key=lambda r: r["time"])
    return outcomes

