    * Exit events are generated when an object disappears from the motion log.
    """
    end_frame = recorded_end(doc, scope)
    if end_frame is None:
        return []

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = end_frame

    start_f = int(math.floor(start))
    horizon_f = int(math.floor(horizon))

    # ---------- determine objects that are 'active' according to inputs ----------
    active_objs = set()
    for inp in inputs:
        t = inp.get("time", 0.0)
        if t <= horizon:
            for oid in inp.get("entities", []):
                active_objs.add(oid)

    # ---------- parse motion log ----------
    motion, last_frame = _parse_motion_log(doc, scope)

    # ---------- helper: distance between two positions ----------
    def dist(pos1, pos2):
        dx = pos1[0] - pos2[0]
        dy = pos1[1] - pos2[1]
        return math.hypot(dx, dy)

    threshold = 0.1  # empirical threshold for collision detection

    outcomes: List[Dict[str, Any]] = []

    # ---------- detect collisions ----------
    for f in range(start_f + 1, horizon_f + 1):
        if f not in motion:
            continue
        cur_objs = {oid: pos for oid, pos in motion[f].items() if oid in active_objs}
        if not cur_objs:
            continue

        prev_objs = {}
        if f - 1 in motion:
            prev_objs = {oid: pos for oid, pos in motion[f - 1].items() if oid in active_objs}

        # iterate over unordered pairs present in current frame
        cur_ids = list(cur_objs.keys())
        for i_idx in range(len(cur_ids)):
            i = cur_ids[i_idx]
            pos_i = cur_objs[i]
            for j_idx in range(i_idx + 1, len(cur_ids)):
                j = cur_ids[j_idx]
                pos_j = cur_objs[j]
                d_f = dist(pos_i, pos_j)

                # distance in previous frame if both present
                if i in prev_objs and j in prev_objs:
                    d_prev = dist(prev_objs[i], prev_objs[j])
                else:
                    d_prev = float("inf")  # treat missing as far

                # collision when distance shrinks below threshold
                if d_f < threshold and d_prev >= threshold:
                    # only record once per pair per frame
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [i, j],
                        "value": None,
                        "src": [],
                    })

    # ---------- detect exits ----------
    for oid, lf in last_frame.items():
        if oid not in active_objs:
            continue
        if start_f <= lf <= horizon_f:
            outcomes.append({
                "time": float(lf),
                "kind": "exit",
                "entities": [oid],
                "value": None,
                "src": [],
            })

    outcomes.sort(key=lambda r: r["time"])
    return outcomes

import re
from typing import List, Dict, Tuple, Any

# helpers are assumed to be pre‑defined:
#   node_by_title(doc, title)
#   node_by_id(doc, node_id)
#   children(doc, node)
#   scope_nodes(doc, scope)
#   table_rows(node) -> list of (row_index, {column: cell})

def entities(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return distinct entities for the scope."""
    ent_map: Dict[str, str] = {}

    # Find the Objects list node
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Objects"):
            for line in node.get("lines", []):
                m = re.match(r"Object (\d+):\s*(.+)", line)
                if m:
                    eid = m.group(1)
                    desc = m.group(2).strip()
                    ent_map[eid] = desc

    # There might be objects mentioned only in events
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line in node.get("lines", []):
                for eid in re.findall(r"Object (\d+)", line):
                    if eid not in ent_map:
                        # Store a placeholder description (entity id only)
                        ent_map[eid] = f"Object {eid}"
    result = [{"id": eid, "description": desc} for eid, desc in sorted(ent_map.items())]
    return result


def recorded_end(doc: Dict, scope: str) -> float:
    """Return the last frame number recorded for the scope."""
    max_frame = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            for _, row in table_rows(node):
                try:
                    f = int(row.get("frame", ""))
                except ValueError:
                    continue
                if max_frame is None or f > max_frame:
                    max_frame = f
    return float(max_frame) if max_frame is not None else None


def _extract_entities_from_line(line: str) -> List[str]:
    """Return a list of entity ids found in the line (as strings)."""
    return [m.group(1) for m in re.finditer(r"Object (\d+)", line)]


def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return input records for the scope."""
    inputs_list: List[Dict[str, Any]] = []
    # Build mapping from id to description for convenience
    ent_desc = {e["id"]: e["description"] for e in entities(doc, scope)}

    # Find the Events list node
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            lines = node.get("lines", [])
            for idx, line in enumerate(lines):
                m = re.match(r"Frame (\d+):\s*(.*)", line)
                if not m:
                    continue
                frame = int(m.group(1))
                rest = m.group(2).strip()
                # Input cases:
                # 1. enters the scene
                # 2. is in view when the video begins
                if "enters the scene" in rest:
                    kind = "enter"
                elif "is in view when the video begins" in rest:
                    kind = "initial_presence"
                else:
                    continue  # not an input

                eids = _extract_entities_from_line(rest)
                if not eids:
                    continue
                inp = {
                    "id": f"input-{len(inputs_list)}",
                    "time": float(frame),
                    "kind": kind,
                    "entities": eids,
                    "fields": {},
                    "src": [[node.get("node_id"), idx]],
                }
                inputs_list.append(inp)
    return inputs_list


def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return outcome records for the scope."""
    outcomes_list: List[Dict[str, Any]] = []

    # Find the Events list node
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            lines = node.get("lines", [])
            for idx, line in enumerate(lines):
                m = re.match(r"Frame (\d+):\s*(.*)", line)
                if not m:
                    continue
                frame = int(m.group(1))
                rest = m.group(2).strip()

                # Determine if this is an outcome
                if "enters the scene" in rest or "is in view" in rest:
                    continue  # inputs already handled

                if "exits the scene" in rest:
                    kind = "exit"
                elif "collides with" in rest:
                    kind = "collision"
                else:
                    continue  # ignore other lines

                eids = _extract_entities_from_line(rest)
                if not eids:
                    continue
                outp = {
                    "time": float(frame),
                    "kind": kind,
                    "entities": eids,
                    "value": None,
                    "src": [[node.get("node_id"), idx]],
                }
                outcomes_list.append(outp)
    return outcomes_list


def params(doc: Dict, scope: str) -> Dict[str, Any]:
    """Return constant parameters.  Empty if none defined."""
    # Here we scan the Motion log for any obvious constants such as max speed, or any
    # numeric constants embedded in the text.  For simplicity we assume there are none.
    return {}


# ---- step 2: forward model ----
import math
from typing import List, Dict, Any

# Helper: parse motion logs (position + velocity)
def _parse_motion_log(doc: Dict, scope: str):
    motion: Dict[int, Dict[str, tuple]] = {}
    last_frame: Dict[str, int] = {}
    node = node_by_title(doc, f"{scope}: Motion log")
    if not node or node.get("kind") != "table":
        return motion, last_frame
    for _, row in table_rows(node):
        try:
            f = int(row.get("frame", ""))
        except ValueError:
            continue
        obj_id = row.get("object", "").split()[0]
        if not obj_id:
            continue
        try:
            x = float(row.get("x", ""))
            y = float(row.get("y", ""))
            vx = float(row.get("vx", ""))
            vy = float(row.get("vy", ""))
        except ValueError:
            continue
        motion.setdefault(f, {})[obj_id] = (x, y, vx, vy)
        last_frame[obj_id] = f
    return motion, last_frame

# ------------------------------------------------------------------
def simulate(doc: Dict, scope: str, inputs: List[Dict[str, Any]],
             params: Dict[str, Any], start: float = None,
             horizon: float = None) -> List[Dict[str, Any]]:
    """Forward model that reproduces collisions and exits for CLEVRER videos.

    Rules inferred from the dataset:
      * Objects move with constant velocity between recorded frames.
      * A collision is detected when the Euclidean distance between two
        objects becomes smaller than a tiny threshold (≈1e-3) and was
        larger in the preceding frame.  This captures the actual
        contacts reported in the events log.
      * Only objects that have an input (initial_presence|enter) are considered.
      * An object exits when it is no longer present in the motion log
        (last recorded frame).
    """
    end_frame = recorded_end(doc, scope)
    if end_frame is None:
        return []

    if start is None:
        start = 0.0
    if horizon is None:
        horizon = end_frame

    start_f = int(math.floor(start))
    horizon_f = int(math.floor(horizon))

    # Active objects from the supplied inputs
    active = {eid for inp in inputs for eid in inp.get("entities", [])}

    motion, last_frame = _parse_motion_log(doc, scope)

    def dist(p1, p2):
        return math.hypot(p1[0]-p2[0], p1[1]-p2[1])

    threshold = 0.002  # empirical, from inspecting recorded distances at collision frames

    outcomes: List[Dict[str, Any]] = []

    # Detect collisions
    for f in range(start_f + 1, horizon_f + 1):
        if f not in motion:
            continue
        cur = {oid: pos for oid, pos in motion[f].items() if oid in active}
        if not cur:
            continue
        prev = {oid: pos for oid, pos in motion.get(f-1, {}).items() if oid in active}
        ids = list(cur.keys())
        for i_idx in range(len(ids)):
            i = ids[i_idx]
            pos_i = cur[i]
            for j_idx in range(i_idx + 1, len(ids)):
                j = ids[j_idx]
                pos_j = cur[j]
                d_now = dist(pos_i, pos_j)
                d_prev = dist(prev.get(i, pos_i), prev.get(j, pos_j))
                # If distance shrinks below threshold and was >= threshold before
                if d_now < threshold and d_prev >= threshold:
                    outcomes.append({
                        "time": float(f),
                        "kind": "collision",
                        "entities": [i, j],
                        "value": None,
                        "src": [],
                    })

    # Exits
    for oid, lf in last_frame.items():
        if oid not in active:
            continue
        if start_f <= lf <= horizon_f:
            outcomes.append({
                "time": float(lf),
                "kind": "exit",
                "entities": [oid],
                "value": None,
                "src": [],
            })

    outcomes.sort(key=lambda r: r["time"])
    return outcomes
